// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type PasswordAnimationProps = Record<string, any>;

const PasswordAnimation: React.FC<PasswordAnimationProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 6,
  textColor = "#f8fafc",
  primaryColor = "#10b981", // Emerald green for success
  warningColor = "#f59e0b", // Amber for medium
  dangerColor = "#ef4444", // Red for weak
  inputBackgroundColor = "#1e293b",
  targetLength = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const startTypingFrame = 30; // 1 second in
  const charsToType = 14; // Type slightly past the goal to show completion
  const framesPerChar = 4;
  const typingDuration = charsToType * framesPerChar;
  
  // Calculate how many characters are currently typed
  const charsTypedRaw = interpolate(
    frame,
    [startTypingFrame, startTypingFrame + typingDuration],
    [0, charsToType],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const currentChars = Math.floor(charsTypedRaw);

  // Entrance animations
  const introSpring = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8 },
  });

  const contentOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  const contentY = interpolate(introSpring, [0, 1], [50, 0]);

  // Progress Bar Logic
  const maxBarChars = 16;
  const barProgress = interpolate(currentChars, [0, maxBarChars], [0, 100], {
    extrapolateRight: "clamp",
  });

  // Determine color based on length
  const barColor = interpolateColors(
    currentChars,
    [0, 6, 8, 10, targetLength, maxBarChars],
    [dangerColor, dangerColor, warningColor, warningColor, primaryColor, primaryColor]
  );

  // Success Pop Animation
  const successFrame = startTypingFrame + targetLength * framesPerChar;
  const successSpring = spring({
    fps,
    frame: frame - successFrame,
    config: { damping: 12, stiffness: 150 },
  });

  const isSuccess = currentChars >= targetLength;
  const inputBorderColor = isSuccess ? primaryColor : "transparent";
  const inputShadow = isSuccess 
    ? `0 0 0 ${interpolate(successSpring, [0, 1], [0, 4])}px ${primaryColor}40`
    : "0 4px 20px rgba(0,0,0,0.2)";
    
  const inputScale = isSuccess ? interpolate(successSpring, [0, 0.5, 1], [1, 1.02, 1]) : 1;

  // Cursor Blink Logic
  const isTyping = frame >= startTypingFrame && frame <= startTypingFrame + typingDuration;
  const blink = Math.floor(frame / 15) % 2 === 0;
  const cursorOpacity = isTyping ? 1 : blink ? 1 : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
          opacity: contentOpacity,
          transform: `translateY(${contentY}px)`,
          transition: "none",
        }}
      >
        {/* Big Counter Header */}
        <div style={{ textAlign: "center", marginBottom: height * 0.08 }}>
          <h1
            style={{
              fontSize: 96,
              fontWeight: 800,
              color: isSuccess ? primaryColor : textColor,
              margin: 0,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {currentChars} / {targetLength}+ chars
          </h1>
        </div>

        {/* Input Interface Area */}
        <div
          style={{
            width: width * 0.6,
            maxWidth: 1152,
            display: "flex",
            flexDirection: "column",
            gap: 24,
            transform: `scale(${inputScale})`,
            transition: "none",
          }}
        >
          {/* Label */}
          <div
            style={{
              display: "flex",
              justifyContent: "flex-start",
              alignItems: "flex-end",
              paddingLeft: 8,
              paddingRight: 8,
            }}
          >
            <span
              style={{
                fontSize: 24,
                fontWeight: 600,
                color: `${textColor}99`,
                textTransform: "uppercase",
                letterSpacing: "0.1em",
              }}
            >
              New Password
            </span>
          </div>

          {/* Password Input Box */}
          <div
            style={{
              width: "100%",
              height: 120,
              backgroundColor: inputBackgroundColor,
              borderRadius: 24,
              border: `2px solid ${inputBorderColor}`,
              boxShadow: inputShadow,
              display: "flex",
              alignItems: "center",
              padding: "0 40px",
              boxSizing: "border-box",
              position: "relative",
              overflow: "hidden",
            }}
          >
            {/* Typed Characters (Dots) */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 16,
                fontFamily: robotoMonoFamily,
              }}
            >
              {Array.from({ length: currentChars }).map((_, i) => (
                <div
                  key={i}
                  style={{
                    width: 24,
                    height: 24,
                    backgroundColor: textColor,
                    borderRadius: "50%",
                    transform: `scale(${interpolate(
                      spring({
                        fps,
                        frame: frame - (startTypingFrame + i * framesPerChar),
                        config: { damping: 10, stiffness: 200 },
                      }),
                      [0, 1],
                      [0, 1]
                    )})`,
                  }}
                />
              ))}

              {/* Blinking Cursor */}
              <div
                style={{
                  width: 4,
                  height: 60,
                  backgroundColor: isSuccess ? primaryColor : textColor,
                  opacity: cursorOpacity,
                  borderRadius: 2,
                  marginLeft: 8,
                }}
              />
            </div>
          </div>

          {/* Strength Progress Bar */}
          <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 12 }}>
            <div
              style={{
                width: "100%",
                height: 12,
                backgroundColor: `${textColor}1a`,
                borderRadius: 6,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  height: "100%",
                  width: `${barProgress}%`,
                  backgroundColor: barColor,
                  borderRadius: 6,
                }}
              />
            </div>
            
            {/* Status Text */}
            <div
              style={{
                fontSize: 20,
                fontWeight: 600,
                color: barColor,
                textAlign: "right",
                opacity: currentChars > 0 ? 1 : 0,
              }}
            >
              {currentChars < 8 ? "Weak" : currentChars < targetLength ? "Good" : "Strong"}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PasswordAnimation;